// Demo: Solid Model Generator - public implementations survey
(function(){'use strict';
var DATA={"label": "Solid Model Generator - public implementations survey", "width": 200, "height": 200, "shapes": [{"kind": "rect", "x": 10, "y": 10, "w": 180, "h": 180, "fill": "#0d1526"}, {"kind": "circle", "cx": 100, "cy": 90, "r": 40, "fill": "#2f7bff"}, {"kind": "text", "x": 60, "y": 160, "size": 16, "fill": "#e8f1ff", "text": "Solid"}]};

