var DATA={"label": "Solid Model Generator definition of done - practitioner disc", "width": 200, "height": 200, "shapes": [{"kind": "rect", "x": 10, "y": 10, "w": 180, "h": 180, "fill": "#0d1526"}, {"kind": "circle", "cx": 100, "cy": 90, "r": 40, "fill": "#2f7bff"}, {"kind": "text", "x": 60, "y": 160, "size": 16, "fill": "#e8f1ff", "text": "definition"}]};

var W=DATA.width,H=DATA.height,els='';
DATA.shapes.forEach(function(sh){
  if(sh.kind==='circle')els+='<circle cx="'+sh.cx+'" cy="'+sh.cy+'" r="'+sh.r+'" fill="'+sh.fill+'"/>';
  else if(sh.kind==='rect')els+='<rect x="'+sh.x+'" y="'+sh.y+'" width="'+sh.w+'" height="'+sh.h+'" fill="'+sh.fill+'"/>';
  else if(sh.kind==='text')els+='<text x="'+sh.x+'" y="'+sh.y+'" font-size="'+sh.size+'" fill="'+sh.fill+'">'+sh.text+'</text>';});
var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">'+els+'</svg>';
console.log('Generated SVG ('+DATA.label+'):');
console.log(svg);
console.log('OK - '+DATA.shapes.length+' shapes, '+svg.length+' chars');
})();

