// Demo: Solid Model Generator handoff protocol - practitioner discipline
(function(){'use strict';
var DATA={"label": "Solid Model Generator handoff protocol - practitioner discip", "w": 41, "h": 27, "depth": 2, "feed": 300, "stepDown": 1};

var w=DATA.w,h=DATA.h,d=DATA.depth,f=DATA.feed;
console.log('G-code pocket '+w+'x'+h+'mm depth '+d+'mm ('+DATA.label+'):');
var L=['G21 (mm)','G90 (absolute)','M3 S12000','G0 Z5','G0 X0 Y0','G1 Z-'+d+' F'+(f/2)];
var passes=Math.ceil(d/DATA.stepDown);
for(var i=1;i<=passes;i++){var z=-(Math.min(i*DATA.stepDown,d));
  L.push('G1 Z'+z.toFixed(2)+' F'+(f/2));
  L.push('G1 X'+w+' F'+f);L.push('G1 Y'+h);L.push('G1 X0');L.push('G1 Y0');}
L.push('G0 Z5');L.push('M5');L.push('M30');
L.forEach(function(l){console.log('  '+l);});
console.log('OK - '+L.length+' lines, '+passes+' depth passes');
})();

